-- Pre-auth callers receive EXECUTE only; table reads remain unavailable.
CREATE ROLE atlas_auth_preauth NOLOGIN;--> statement-breakpoint
REVOKE ALL ON auth_rate_buckets, auth_security_events, auth_outbox, auth_transactions FROM atlas_auth_gateway, atlas_auth_preauth;--> statement-breakpoint
CREATE OR REPLACE FUNCTION atlas_auth_admit_pre_auth(p_bucket text, p_purpose text, p_command text, p_now timestamptz) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $$ DECLARE bucket_count integer; BEGIN IF length(p_bucket) < 32 OR p_purpose !~ '^[a-z_]{3,64}$' OR length(p_command) < 16 THEN RAISE EXCEPTION 'auth_preauth_input_denied'; END IF; INSERT INTO public.auth_rate_buckets (bucket_digest, purpose, count, window_started_at, expires_at, updated_at) VALUES (p_bucket,p_purpose,1,p_now,p_now + interval '1 minute',p_now) ON CONFLICT (bucket_digest) DO UPDATE SET count = CASE WHEN auth_rate_buckets.expires_at <= excluded.window_started_at THEN 1 ELSE auth_rate_buckets.count + 1 END, window_started_at = CASE WHEN auth_rate_buckets.expires_at <= excluded.window_started_at THEN excluded.window_started_at ELSE auth_rate_buckets.window_started_at END, expires_at = CASE WHEN auth_rate_buckets.expires_at <= excluded.window_started_at THEN excluded.expires_at ELSE auth_rate_buckets.expires_at END, updated_at = excluded.updated_at RETURNING count INTO bucket_count; IF bucket_count > 10 THEN RETURN false; END IF; INSERT INTO public.auth_security_events (id, account_id, sequence, event_name, outcome, correlation_id, policy_version, occurred_at) VALUES (p_command || ':audit',NULL,1,p_purpose,'accepted',p_command,1,p_now) ON CONFLICT (id) DO NOTHING; INSERT INTO public.auth_outbox (command_id, account_id, purpose, idempotency_key, state, attempt_count, lease_version, available_at, payload, created_at, updated_at) VALUES (p_command,NULL,p_purpose,p_command,'pending',0,0,p_now,'{}'::jsonb,p_now,p_now) ON CONFLICT (command_id) DO NOTHING; RETURN true; END; $$;--> statement-breakpoint
REVOKE ALL ON FUNCTION atlas_auth_admit_pre_auth(text,text,text,timestamptz) FROM PUBLIC;--> statement-breakpoint
GRANT EXECUTE ON FUNCTION atlas_auth_admit_pre_auth(text,text,text,timestamptz) TO atlas_auth_preauth, atlas_auth_gateway;--> statement-breakpoint
